1	-- Module: nomor tiket fisik manual per unit, selain serial_no otomatis yang
2	-- sudah ada. Buku tiket kertas terpisah per kategori, jadi keunikan nomor
3	-- fisik di-scope per kategori juga (business_id, ticket_category_id,
4	-- manual_number) — sama seperti serial_no.
5	
6	-- Backfill-safe: baris yang sudah ada dapat manual_number = serial_no
7	-- supaya kolom bisa langsung NOT NULL di migration yang sama.
8	alter table public.ticket_serials
9	  add column manual_number text;
10	
11	update public.ticket_serials
12	  set manual_number = serial_no::text
13	  where manual_number is null;
14	
15	alter table public.ticket_serials
16	  alter column manual_number set not null;
17	
18	alter table public.ticket_serials
19	  add constraint ticket_serials_manual_number_not_blank
20	  check (length(trim(manual_number)) > 0);
21	
22	create unique index ticket_serials_business_id_category_id_manual_number_key
23	  on public.ticket_serials (business_id, ticket_category_id, manual_number);
24	
25	-- checkout_ticket_transaction: p_items berubah dari
26	-- [{ticket_category_id, qty}] jadi [{ticket_category_id, manual_numbers: string[]}].
27	-- Logika harga/hari-libur/member/pajak/service TIDAK berubah sama sekali,
28	-- cuma loop insert per-unit yang berubah bentuk.
29	create or replace function public.checkout_ticket_transaction(
30	  p_business_id uuid,
31	  p_cashier_id uuid,
32	  p_items jsonb, -- array of {ticket_category_id, manual_numbers: string[]}
33	  p_payment_method text,
34	  p_received numeric default null,
35	  p_member_id uuid default null
36	)
37	returns table (transaction_id uuid, invoice_number text)
38	language plpgsql
39	security definer
40	set search_path = ''
41	as $$
42	declare
43	  v_business record;
44	  v_member record;
45	  v_invoice_number text;
46	  v_seq int;
47	  v_is_holiday boolean;
48	  v_subtotal numeric(12, 2) := 0;
49	  v_service numeric(12, 2) := 0;
50	  v_tax numeric(12, 2) := 0;
51	  v_total numeric(12, 2);
52	  v_change numeric(12, 2);
53	  v_transaction_id uuid;
54	  v_shift_id uuid;
55	  v_item jsonb;
56	  v_category_id uuid;
57	  v_category record;
58	  v_manual_numbers jsonb;
59	  v_manual_number text;
60	  v_use_member_price boolean := false;
61	  v_unit_price numeric(12, 2);
62	  v_serial int;
63	begin
64	  if not private.owns_business(p_business_id) then
65	    raise exception 'not authorized';
66	  end if;
67	
68	  if not exists (
69	    select 1 from public.cashiers c
70	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
71	  ) then
72	    raise exception 'invalid cashier';
73	  end if;
74	
75	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
76	    raise exception 'payment method required';
77	  end if;
78	
79	  if p_items is null or jsonb_array_length(p_items) = 0 then
80	    raise exception 'cart is empty';
81	  end if;
82	
83	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
84	  into v_business
85	  from public.businesses b
86	  where b.id = p_business_id;
87	
88	  select id into v_shift_id
89	  from public.shifts
90	  where business_id = p_business_id and closed_at is null
91	  limit 1;
92	
93	  if v_shift_id is null then
94	    raise exception 'no active shift — open a shift before selling';
95	  end if;
96	
97	  if p_member_id is not null then
98	    select m.id, m.valid_from, m.valid_until
99	    into v_member
100	    from public.members m
101	    where m.id = p_member_id
102	      and m.business_id = p_business_id
103	      and m.deleted_at is null;
104	
105	    if not found then
106	      raise exception 'member not found';
107	    end if;
108	
109	    if current_date < v_member.valid_from or current_date > v_member.valid_until then
110	      raise exception 'membership tidak aktif (kadaluarsa atau belum berlaku)';
111	    end if;
112	
113	    v_use_member_price := true;
114	  end if;
115	
116	  v_is_holiday := extract(dow from current_date) in (0, 6)
117	    or exists (
118	      select 1 from public.ticket_holidays h
119	      where h.business_id = p_business_id and h.holiday_date = current_date
120	    );
121	
122	  select count(*) + 1 into v_seq
123	  from public.ticket_transactions t
124	  where t.business_id = p_business_id
125	    and t.date::date = current_date;
126	
127	  v_invoice_number := 'TIX-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
128	
129	  insert into public.ticket_transactions (
130	    business_id, shift_id, cashier_id, member_id, invoice_number, date,
131	    is_holiday, subtotal, service, tax, total, payment_method, received, change
132	  ) values (
133	    p_business_id, v_shift_id, p_cashier_id, p_member_id, v_invoice_number, now(),
134	    v_is_holiday, 0, 0, 0, 0, p_payment_method, p_received, 0
135	  )
136	  returning id into v_transaction_id;
137	
138	  for v_item in select * from jsonb_array_elements(p_items)
139	  loop
140	    v_category_id := (v_item ->> 'ticket_category_id')::uuid;
141	    v_manual_numbers := v_item -> 'manual_numbers';
142	
143	    if v_manual_numbers is null or jsonb_typeof(v_manual_numbers) <> 'array'
144	      or jsonb_array_length(v_manual_numbers) = 0 then
145	      raise exception 'manual ticket numbers required for category %', v_category_id;
146	    end if;
147	
148	    select * into v_category
149	    from public.ticket_categories
150	    where id = v_category_id
151	      and business_id = p_business_id
152	      and deleted_at is null
153	    for update;
154	
155	    if not found then
156	      raise exception 'ticket category not found: %', v_category_id;
157	    end if;
158	
159	    v_unit_price := case
160	      when v_use_member_price then v_category.member_price
161	      when v_is_holiday then v_category.price_holiday
162	      else v_category.price_weekday
163	    end;
164	
165	    for v_manual_number in select jsonb_array_elements_text(v_manual_numbers)
166	    loop
167	      if v_manual_number is null or length(trim(v_manual_number)) = 0 then
168	        raise exception 'nomor tiket fisik tidak boleh kosong (kategori %)', v_category.name;
169	      end if;
170	
171	      v_serial := v_category.next_serial;
172	
173	      insert into public.ticket_serials (
174	        ticket_transaction_id, ticket_category_id, business_id,
175	        serial_no, manual_number, price, is_member_price
176	      ) values (
177	        v_transaction_id, v_category_id, p_business_id,
178	        v_serial, trim(v_manual_number), v_unit_price, v_use_member_price
179	      );
180	
181	      v_category.next_serial := v_category.next_serial + 1;
182	      v_subtotal := v_subtotal + v_unit_price;
183	    end loop;
184	
185	    update public.ticket_categories
186	    set next_serial = v_category.next_serial
187	    where id = v_category_id;
188	  end loop;
189	
190	  if v_business.service_enabled then
191	    v_service := round(v_subtotal * v_business.service_rate / 100);
192	  end if;
193	
194	  if v_business.tax_enabled then
195	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
196	  end if;
197	
198	  v_total := v_subtotal + v_service + v_tax;
199	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
200	
201	  update public.ticket_transactions
202	  set subtotal = v_subtotal,
203	      service = v_service,
204	      tax = v_tax,
205	      total = v_total,
206	      change = v_change
207	  where id = v_transaction_id;
208	
209	  return query select v_transaction_id, v_invoice_number;
210	end;
211	$$;
212	
213	grant execute on function public.checkout_ticket_transaction(uuid, uuid, jsonb, text, numeric, uuid) to authenticated;
