1	-- Mini-ERP accounting module, part 2: auto-post journal entries from the two
2	-- highest-volume money flows — sales (checkout_transaction) and voids
3	-- (void_transaction). Everything else about these RPCs is unchanged; the
4	-- only addition is a call to private.post_journal() near the end.
5	
6	drop function if exists public.checkout_transaction(
7	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[]
8	);
9	
10	create or replace function public.checkout_transaction(
11	  p_business_id uuid,
12	  p_cashier_id uuid,
13	  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
14	  p_payment_method text,
15	  p_received numeric default null,
16	  p_order_disc numeric default 0,
17	  p_order_disc_type text default 'pct',
18	  p_customer_id uuid default null,
19	  p_self_order_ids uuid[] default null
20	)
21	returns table (transaction_id uuid, invoice_number text)
22	language plpgsql
23	security definer
24	set search_path = ''
25	as $$
26	declare
27	  v_business record;
28	  v_invoice_number text;
29	  v_seq int;
30	  v_subtotal_raw numeric(12, 2) := 0;
31	  v_total_item_disc numeric(12, 2) := 0;
32	  v_order_disc_amt numeric(12, 2) := 0;
33	  v_subtotal numeric(12, 2);
34	  v_service numeric(12, 2) := 0;
35	  v_tax numeric(12, 2) := 0;
36	  v_total numeric(12, 2);
37	  v_total_cost numeric(12, 2) := 0;
38	  v_transaction_id uuid;
39	  v_item jsonb;
40	  v_qty numeric(12, 2);
41	  v_product_id uuid;
42	  v_product record;
43	  v_line_gross numeric(12, 2);
44	  v_disc numeric(12, 2);
45	  v_disc_type text;
46	  v_item_disc numeric(12, 2);
47	  v_change numeric(12, 2);
48	  v_shift_id uuid;
49	  v_recipe record;
50	  v_table_id uuid;
51	  v_journal_lines jsonb;
52	begin
53	  if not private.owns_business(p_business_id) then
54	    raise exception 'not authorized';
55	  end if;
56	
57	  if not exists (
58	    select 1 from public.cashiers c
59	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
60	  ) then
61	    raise exception 'invalid cashier';
62	  end if;
63	
64	  if p_customer_id is not null and not exists (
65	    select 1 from public.customers c
66	    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
67	  ) then
68	    raise exception 'invalid customer';
69	  end if;
70	
71	  if p_self_order_ids is not null and exists (
72	    select 1 from public.self_orders so
73	    where so.id = any(p_self_order_ids) and so.business_id <> p_business_id
74	  ) then
75	    raise exception 'invalid self order';
76	  end if;
77	
78	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
79	    raise exception 'payment method required';
80	  end if;
81	
82	  if p_items is null or jsonb_array_length(p_items) = 0 then
83	    raise exception 'cart is empty';
84	  end if;
85	
86	  if p_order_disc_type not in ('pct', 'amt') then
87	    raise exception 'invalid order discount type';
88	  end if;
89	
90	  if p_order_disc is null or p_order_disc < 0
91	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
92	    raise exception 'invalid order discount';
93	  end if;
94	
95	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
96	  into v_business
97	  from public.businesses b
98	  where b.id = p_business_id;
99	
100	  select id into v_shift_id
101	  from public.shifts
102	  where business_id = p_business_id and closed_at is null
103	  limit 1;
104	
105	  if v_shift_id is null then
106	    raise exception 'no active shift — open a shift before selling';
107	  end if;
108	
109	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
110	    select table_id into v_table_id
111	    from public.self_orders
112	    where id = p_self_order_ids[1];
113	  end if;
114	
115	  select count(*) + 1 into v_seq
116	  from public.transactions t
117	  where t.business_id = p_business_id
118	    and t.date::date = current_date;
119	
120	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
121	
122	  insert into public.transactions (
123	    business_id, shift_id, cashier_id, customer_id, table_id, invoice_number, date,
124	    subtotal_raw, subtotal, total, total_cost, gross_profit
125	  ) values (
126	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_table_id, v_invoice_number, now(),
127	    0, 0, 0, 0, 0
128	  )
129	  returning id into v_transaction_id;
130	
131	  for v_item in select * from jsonb_array_elements(p_items)
132	  loop
133	    v_product_id := (v_item ->> 'product_id')::uuid;
134	    v_qty := (v_item ->> 'qty')::numeric;
135	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
136	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
137	
138	    if v_qty is null or v_qty <= 0 then
139	      raise exception 'invalid quantity';
140	    end if;
141	
142	    if v_disc_type not in ('pct', 'amt') then
143	      raise exception 'invalid item discount type';
144	    end if;
145	
146	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
147	      raise exception 'invalid item discount';
148	    end if;
149	
150	    select * into v_product
151	    from public.products p
152	    where p.id = v_product_id
153	      and p.business_id = p_business_id
154	      and p.deleted_at is null;
155	
156	    if not found then
157	      raise exception 'product not found: %', v_product_id;
158	    end if;
159	
160	    v_line_gross := v_product.price * v_qty;
161	    v_item_disc := case v_disc_type
162	      when 'pct' then round(v_line_gross * v_disc / 100)
163	      else least(v_disc * v_qty, v_line_gross)
164	    end;
165	
166	    insert into public.transaction_items (
167	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
168	    ) values (
169	      v_transaction_id, v_product.id, v_product.name, v_product.category,
170	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
171	    );
172	
173	    update public.products
174	    set stock = greatest(0, stock - v_qty)
175	    where id = v_product_id;
176	
177	    -- Consume ingredients per the product's recipe (if any).
178	    for v_recipe in
179	      select pr.ingredient_id, pr.qty as recipe_qty
180	      from public.product_recipes pr
181	      where pr.product_id = v_product_id and pr.ingredient_id is not null
182	    loop
183	      insert into public.transaction_ingredient_consumption (
184	        transaction_id, ingredient_id, qty
185	      ) values (
186	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
187	      );
188	
189	      update public.ingredients
190	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
191	      where id = v_recipe.ingredient_id;
192	    end loop;
193	
194	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
195	    v_total_item_disc := v_total_item_disc + v_item_disc;
196	    v_total_cost := v_total_cost + v_product.cost * v_qty;
197	  end loop;
198	
199	  v_order_disc_amt := case p_order_disc_type
200	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
201	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
202	  end;
203	
204	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
205	
206	  if v_business.service_enabled then
207	    v_service := round(v_subtotal * v_business.service_rate / 100);
208	  end if;
209	
210	  if v_business.tax_enabled then
211	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
212	  end if;
213	
214	  v_total := v_subtotal + v_service + v_tax;
215	
216	  update public.transactions
217	  set subtotal_raw = v_subtotal_raw,
218	      subtotal = v_subtotal,
219	      total_item_disc = v_total_item_disc,
220	      order_disc_amt = v_order_disc_amt,
221	      service = v_service,
222	      tax = v_tax,
223	      total = v_total,
224	      total_cost = v_total_cost,
225	      gross_profit = v_subtotal - v_total_cost
226	  where id = v_transaction_id;
227	
228	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
229	
230	  insert into public.transaction_payments (
231	    transaction_id, method, amount, received, change
232	  ) values (
233	    v_transaction_id, p_payment_method, v_total, p_received, v_change
234	  );
235	
236	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
237	    update public.self_orders
238	    set status = 'selesai'
239	    where id = any(p_self_order_ids)
240	      and business_id = p_business_id
241	      and status <> 'selesai';
242	  end if;
243	
244	  -- Auto-post the sale to the journal: Kas & Bank / Pendapatan Penjualan,
245	  -- plus HPP / Persediaan if this sale had recipe-based cost data.
246	  if v_total > 0 then
247	    v_journal_lines := jsonb_build_array(
248	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
249	      jsonb_build_object('account_code', '4-001', 'debit', 0, 'credit', v_total)
250	    );
251	    if v_total_cost > 0 then
252	      v_journal_lines := v_journal_lines || jsonb_build_array(
253	        jsonb_build_object('account_code', '5-001', 'debit', v_total_cost, 'credit', 0),
254	        jsonb_build_object('account_code', '1-200', 'debit', 0, 'credit', v_total_cost)
255	      );
256	    end if;
257	    perform private.post_journal(
258	      p_business_id, now(), 'Penjualan ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
259	    );
260	  end if;
261	
262	  return query select v_transaction_id, v_invoice_number;
263	end;
264	$$;
265	
266	grant execute on function public.checkout_transaction(
267	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[]
268	) to authenticated;
