270	-- Void: reverse the original sale's journal entry (swap debit/credit) -------
271	
272	create or replace function public.void_transaction(
273	  p_business_id uuid,
274	  p_transaction_id uuid,
275	  p_manager_pin text,
276	  p_reason text default null
277	)
278	returns table (voided_by_name text)
279	language plpgsql
280	security definer
281	set search_path = ''
282	as $$
283	declare
284	  v_manager record;
285	  v_tx record;
286	  v_journal_lines jsonb;
287	begin
288	  if not private.owns_business(p_business_id) then
289	    raise exception 'not authorized';
290	  end if;
291	
292	  -- Hanya PIN milik manajer aktif dari bisnis ini yang diterima. Pesan error
293	  -- sengaja tidak membedakan "PIN salah" vs "bukan manajer".
294	  select c.id, c.name
295	  into v_manager
296	  from public.cashiers c
297	  where c.business_id = p_business_id
298	    and c.role = 'manajer'
299	    and c.active
300	    and c.pin_hash = extensions.crypt(p_manager_pin, c.pin_hash)
301	  limit 1;
302	
303	  if not found then
304	    raise exception 'PIN salah atau tidak memiliki otorisasi';
305	  end if;
306	
307	  select t.id, t.voided, t.total, t.total_cost, t.invoice_number
308	  into v_tx
309	  from public.transactions t
310	  where t.id = p_transaction_id
311	    and t.business_id = p_business_id
312	  for update;
313	
314	  if not found then
315	    raise exception 'transaction not found';
316	  end if;
317	
318	  if v_tx.voided then
319	    raise exception 'transaksi sudah dibatalkan';
320	  end if;
321	
322	  -- Kembalikan stok produk yang terjual (produk yang sudah dihapus dilewati,
323	  -- sama seperti aplikasi lama).
324	  update public.products p
325	  set stock = p.stock + ti.qty
326	  from public.transaction_items ti
327	  where ti.transaction_id = p_transaction_id
328	    and ti.product_id = p.id
329	    and p.deleted_at is null;
330	
331	  -- Kembalikan stok bahan baku yang terkonsumsi resep saat checkout.
332	  update public.ingredients i
333	  set stock = i.stock + tic.qty
334	  from public.transaction_ingredient_consumption tic
335	  where tic.transaction_id = p_transaction_id
336	    and tic.ingredient_id = i.id;
337	
338	  update public.transactions
339	  set voided = true,
340	      voided_at = now(),
341	      void_reason = nullif(left(trim(p_reason), 200), ''),
342	      voided_by = v_manager.id
343	  where id = p_transaction_id;
344	
345	  if v_tx.total > 0 then
346	    v_journal_lines := jsonb_build_array(
347	      jsonb_build_object('account_code', '4-001', 'debit', v_tx.total, 'credit', 0),
348	      jsonb_build_object('account_code', '1-001', 'debit', 0, 'credit', v_tx.total)
349	    );
350	    if v_tx.total_cost > 0 then
351	      v_journal_lines := v_journal_lines || jsonb_build_array(
352	        jsonb_build_object('account_code', '1-200', 'debit', v_tx.total_cost, 'credit', 0),
353	        jsonb_build_object('account_code', '5-001', 'debit', 0, 'credit', v_tx.total_cost)
354	      );
355	    end if;
356	    perform private.post_journal(
357	      p_business_id, now(), 'Void ' || v_tx.invoice_number, 'void', p_transaction_id, v_journal_lines
358	    );
359	  end if;
360	
361	  return query select v_manager.name;
362	end;
