1	-- Fix: a 100%-discounted sale (v_total = 0) still consumes stock/ingredients
2	-- and has real COGS (v_total_cost > 0), but the journal posting was gated on
3	-- `v_total > 0` for the whole entry — so its HPP/Persediaan lines silently
4	-- never got posted. Decouple the two: post the Kas & Bank/Pendapatan lines
5	-- only when there's revenue, and the HPP/Persediaan lines independently
6	-- whenever there's cost, in whichever combination applies. Same fix mirrored
7	-- in void_transaction's reversing entry. No signature changes.
8	
9	create or replace function public.checkout_transaction(
10	  p_business_id uuid,
11	  p_cashier_id uuid,
12	  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
13	  p_payment_method text,
14	  p_received numeric default null,
15	  p_order_disc numeric default 0,
16	  p_order_disc_type text default 'pct',
17	  p_customer_id uuid default null,
18	  p_self_order_ids uuid[] default null
19	)
20	returns table (transaction_id uuid, invoice_number text)
21	language plpgsql
22	security definer
23	set search_path = ''
24	as $$
25	declare
26	  v_business record;
27	  v_invoice_number text;
28	  v_seq int;
29	  v_subtotal_raw numeric(12, 2) := 0;
30	  v_total_item_disc numeric(12, 2) := 0;
31	  v_order_disc_amt numeric(12, 2) := 0;
32	  v_subtotal numeric(12, 2);
33	  v_service numeric(12, 2) := 0;
34	  v_tax numeric(12, 2) := 0;
35	  v_total numeric(12, 2);
36	  v_total_cost numeric(12, 2) := 0;
37	  v_transaction_id uuid;
38	  v_item jsonb;
39	  v_qty numeric(12, 2);
40	  v_product_id uuid;
41	  v_product record;
42	  v_line_gross numeric(12, 2);
43	  v_disc numeric(12, 2);
44	  v_disc_type text;
45	  v_item_disc numeric(12, 2);
46	  v_change numeric(12, 2);
47	  v_shift_id uuid;
48	  v_recipe record;
49	  v_table_id uuid;
50	  v_journal_lines jsonb;
51	begin
52	  if not private.owns_business(p_business_id) then
53	    raise exception 'not authorized';
54	  end if;
55	
56	  if not exists (
57	    select 1 from public.cashiers c
58	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
59	  ) then
60	    raise exception 'invalid cashier';
61	  end if;
62	
63	  if p_customer_id is not null and not exists (
64	    select 1 from public.customers c
65	    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
66	  ) then
67	    raise exception 'invalid customer';
68	  end if;
69	
70	  if p_self_order_ids is not null and exists (
71	    select 1 from public.self_orders so
72	    where so.id = any(p_self_order_ids) and so.business_id <> p_business_id
73	  ) then
74	    raise exception 'invalid self order';
75	  end if;
76	
77	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
78	    raise exception 'payment method required';
79	  end if;
80	
81	  if p_items is null or jsonb_array_length(p_items) = 0 then
82	    raise exception 'cart is empty';
83	  end if;
84	
85	  if p_order_disc_type not in ('pct', 'amt') then
86	    raise exception 'invalid order discount type';
87	  end if;
88	
89	  if p_order_disc is null or p_order_disc < 0
90	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
91	    raise exception 'invalid order discount';
92	  end if;
93	
94	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
95	  into v_business
96	  from public.businesses b
97	  where b.id = p_business_id;
98	
99	  select id into v_shift_id
100	  from public.shifts
101	  where business_id = p_business_id and closed_at is null
102	  limit 1;
103	
104	  if v_shift_id is null then
105	    raise exception 'no active shift — open a shift before selling';
106	  end if;
107	
108	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
109	    select table_id into v_table_id
110	    from public.self_orders
111	    where id = p_self_order_ids[1];
112	  end if;
113	
114	  select count(*) + 1 into v_seq
115	  from public.transactions t
116	  where t.business_id = p_business_id
117	    and t.date::date = current_date;
118	
119	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
120	
121	  insert into public.transactions (
122	    business_id, shift_id, cashier_id, customer_id, table_id, invoice_number, date,
123	    subtotal_raw, subtotal, total, total_cost, gross_profit
124	  ) values (
125	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_table_id, v_invoice_number, now(),
126	    0, 0, 0, 0, 0
127	  )
128	  returning id into v_transaction_id;
129	
130	  for v_item in select * from jsonb_array_elements(p_items)
131	  loop
132	    v_product_id := (v_item ->> 'product_id')::uuid;
133	    v_qty := (v_item ->> 'qty')::numeric;
134	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
135	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
136	
137	    if v_qty is null or v_qty <= 0 then
138	      raise exception 'invalid quantity';
139	    end if;
140	
141	    if v_disc_type not in ('pct', 'amt') then
142	      raise exception 'invalid item discount type';
143	    end if;
144	
145	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
146	      raise exception 'invalid item discount';
147	    end if;
148	
149	    select * into v_product
150	    from public.products p
151	    where p.id = v_product_id
152	      and p.business_id = p_business_id
153	      and p.deleted_at is null;
154	
155	    if not found then
156	      raise exception 'product not found: %', v_product_id;
157	    end if;
158	
159	    v_line_gross := v_product.price * v_qty;
160	    v_item_disc := case v_disc_type
161	      when 'pct' then round(v_line_gross * v_disc / 100)
162	      else least(v_disc * v_qty, v_line_gross)
163	    end;
164	
165	    insert into public.transaction_items (
166	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
167	    ) values (
168	      v_transaction_id, v_product.id, v_product.name, v_product.category,
169	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
170	    );
171	
172	    update public.products
173	    set stock = greatest(0, stock - v_qty)
174	    where id = v_product_id;
175	
176	    -- Consume ingredients per the product's recipe (if any).
177	    for v_recipe in
178	      select pr.ingredient_id, pr.qty as recipe_qty
179	      from public.product_recipes pr
180	      where pr.product_id = v_product_id and pr.ingredient_id is not null
181	    loop
182	      insert into public.transaction_ingredient_consumption (
183	        transaction_id, ingredient_id, qty
184	      ) values (
185	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
186	      );
187	
188	      update public.ingredients
189	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
190	      where id = v_recipe.ingredient_id;
191	    end loop;
192	
193	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
194	    v_total_item_disc := v_total_item_disc + v_item_disc;
195	    v_total_cost := v_total_cost + v_product.cost * v_qty;
196	  end loop;
197	
198	  v_order_disc_amt := case p_order_disc_type
199	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
200	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
201	  end;
202	
203	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
204	
205	  if v_business.service_enabled then
206	    v_service := round(v_subtotal * v_business.service_rate / 100);
207	  end if;
208	
209	  if v_business.tax_enabled then
210	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
211	  end if;
212	
213	  v_total := v_subtotal + v_service + v_tax;
214	
215	  update public.transactions
216	  set subtotal_raw = v_subtotal_raw,
217	      subtotal = v_subtotal,
218	      total_item_disc = v_total_item_disc,
219	      order_disc_amt = v_order_disc_amt,
220	      service = v_service,
221	      tax = v_tax,
222	      total = v_total,
223	      total_cost = v_total_cost,
224	      gross_profit = v_subtotal - v_total_cost
225	  where id = v_transaction_id;
226	
227	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
228	
229	  insert into public.transaction_payments (
230	    transaction_id, method, amount, received, change
231	  ) values (
232	    v_transaction_id, p_payment_method, v_total, p_received, v_change
233	  );
234	
235	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
236	    update public.self_orders
237	    set status = 'selesai'
238	    where id = any(p_self_order_ids)
239	      and business_id = p_business_id
240	      and status <> 'selesai';
241	  end if;
242	
243	  -- Auto-post the sale to the journal: Kas & Bank / Pendapatan Penjualan
244	  -- (only if there's actual revenue), plus HPP / Persediaan independently
245	  -- whenever this sale had recipe-based cost data — even on a 100%-discount
246	  -- sale where v_total is 0 but stock/ingredients were still consumed.
247	  v_journal_lines := '[]'::jsonb;
248	  if v_total > 0 then
249	    v_journal_lines := v_journal_lines || jsonb_build_array(
250	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
251	      jsonb_build_object('account_code', '4-001', 'debit', 0, 'credit', v_total)
252	    );
253	  end if;
254	  if v_total_cost > 0 then
255	    v_journal_lines := v_journal_lines || jsonb_build_array(
256	      jsonb_build_object('account_code', '5-001', 'debit', v_total_cost, 'credit', 0),
257	      jsonb_build_object('account_code', '1-200', 'debit', 0, 'credit', v_total_cost)
258	    );
259	  end if;
260	  if jsonb_array_length(v_journal_lines) >= 2 then
261	    perform private.post_journal(
262	      p_business_id, now(), 'Penjualan ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
263	    );
264	  end if;
265	
266	  return query select v_transaction_id, v_invoice_number;
267	end;
268	$$;
269	
270	grant execute on function public.checkout_transaction(
271	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[]
272	) to authenticated;
