274	-- Void: reverse the original sale's journal entry (swap debit/credit) -------
275	
276	create or replace function public.void_transaction(
277	  p_business_id uuid,
278	  p_transaction_id uuid,
279	  p_manager_pin text,
280	  p_reason text default null
281	)
282	returns table (voided_by_name text)
283	language plpgsql
284	security definer
285	set search_path = ''
286	as $$
287	declare
288	  v_manager record;
289	  v_tx record;
290	  v_journal_lines jsonb;
291	begin
292	  if not private.owns_business(p_business_id) then
293	    raise exception 'not authorized';
294	  end if;
295	
296	  -- Hanya PIN milik manajer aktif dari bisnis ini yang diterima. Pesan error
297	  -- sengaja tidak membedakan "PIN salah" vs "bukan manajer".
298	  select c.id, c.name
299	  into v_manager
300	  from public.cashiers c
301	  where c.business_id = p_business_id
302	    and c.role = 'manajer'
303	    and c.active
304	    and c.pin_hash = extensions.crypt(p_manager_pin, c.pin_hash)
305	  limit 1;
306	
307	  if not found then
308	    raise exception 'PIN salah atau tidak memiliki otorisasi';
309	  end if;
310	
311	  select t.id, t.voided, t.total, t.total_cost, t.invoice_number
312	  into v_tx
313	  from public.transactions t
314	  where t.id = p_transaction_id
315	    and t.business_id = p_business_id
316	  for update;
317	
318	  if not found then
319	    raise exception 'transaction not found';
320	  end if;
321	
322	  if v_tx.voided then
323	    raise exception 'transaksi sudah dibatalkan';
324	  end if;
325	
326	  -- Kembalikan stok produk yang terjual (produk yang sudah dihapus dilewati,
327	  -- sama seperti aplikasi lama).
328	  update public.products p
329	  set stock = p.stock + ti.qty
330	  from public.transaction_items ti
331	  where ti.transaction_id = p_transaction_id
332	    and ti.product_id = p.id
333	    and p.deleted_at is null;
334	
335	  -- Kembalikan stok bahan baku yang terkonsumsi resep saat checkout.
336	  update public.ingredients i
337	  set stock = i.stock + tic.qty
338	  from public.transaction_ingredient_consumption tic
339	  where tic.transaction_id = p_transaction_id
340	    and tic.ingredient_id = i.id;
341	
342	  update public.transactions
343	  set voided = true,
344	      voided_at = now(),
345	      void_reason = nullif(left(trim(p_reason), 200), ''),
346	      voided_by = v_manager.id
347	  where id = p_transaction_id;
348	
349	  v_journal_lines := '[]'::jsonb;
350	  if v_tx.total > 0 then
351	    v_journal_lines := v_journal_lines || jsonb_build_array(
352	      jsonb_build_object('account_code', '4-001', 'debit', v_tx.total, 'credit', 0),
353	      jsonb_build_object('account_code', '1-001', 'debit', 0, 'credit', v_tx.total)
354	    );
355	  end if;
356	  if v_tx.total_cost > 0 then
357	    v_journal_lines := v_journal_lines || jsonb_build_array(
358	      jsonb_build_object('account_code', '1-200', 'debit', v_tx.total_cost, 'credit', 0),
359	      jsonb_build_object('account_code', '5-001', 'debit', 0, 'credit', v_tx.total_cost)
360	    );
361	  end if;
362	  if jsonb_array_length(v_journal_lines) >= 2 then
363	    perform private.post_journal(
364	      p_business_id, now(), 'Void ' || v_tx.invoice_number, 'void', p_transaction_id, v_journal_lines
365	    );
366	  end if;
367	
368	  return query select v_manager.name;
369	end;
370	$$;
371	
372	grant execute on function public.void_transaction(uuid, uuid, text, text) to authenticated;
