1	-- Fix: checkout_transaction credited the full transaction total — including
2	-- PPN collected from the customer — straight to 4-001 Pendapatan Penjualan.
3	-- PPN isn't the business's revenue, it's a liability owed to the tax office,
4	-- so it was overstating income and had nowhere to show up under Kewajiban.
5	-- Adds a dedicated 2-200 PPN Keluaran (Utang Pajak) account and splits the
6	-- sale's Kas & Bank debit across Pendapatan Penjualan (subtotal + service)
7	-- and PPN Keluaran (tax) instead of crediting it all to revenue. Mirrored in
8	-- void_transaction's reversing entry. Remitting the PPN later (paying it to
9	-- the tax office) can be recorded as a manual journal entry (debit 2-200,
10	-- credit 1-001) via the existing Jurnal Manual page — no new UI needed since
11	-- that page already lists every account dynamically.
12	create or replace function private.seed_default_accounts(p_business_id uuid)
13	returns void
14	language plpgsql
15	security definer
16	set search_path = ''
17	as $$
18	begin
19	  insert into public.accounts (business_id, code, name, type, normal_balance, is_system)
20	  values
21	    (p_business_id, '1-001', 'Kas & Bank', 'aset', 'debit', true),
22	    (p_business_id, '1-100', 'Piutang Usaha', 'aset', 'debit', true),
23	    (p_business_id, '1-200', 'Persediaan', 'aset', 'debit', true),
24	    (p_business_id, '1-500', 'Peralatan', 'aset', 'debit', true),
25	    (p_business_id, '2-001', 'Utang Dagang', 'kewajiban', 'kredit', true),
26	    (p_business_id, '2-100', 'Utang Gaji', 'kewajiban', 'kredit', true),
27	    (p_business_id, '2-200', 'PPN Keluaran (Utang Pajak)', 'kewajiban', 'kredit', true),
28	    (p_business_id, '3-001', 'Modal Pemilik', 'modal', 'kredit', true),
29	    (p_business_id, '3-100', 'Laba Ditahan', 'modal', 'kredit', true),
30	    (p_business_id, '4-001', 'Pendapatan Penjualan', 'pendapatan', 'kredit', true),
31	    (p_business_id, '5-001', 'Beban Pokok Penjualan (HPP)', 'beban', 'debit', true),
32	    (p_business_id, '5-100', 'Beban Gaji', 'beban', 'debit', true),
33	    (p_business_id, '5-101', 'Beban Listrik & Air', 'beban', 'debit', true),
