166	    subtotal_raw, subtotal, total, total_cost, gross_profit
167	  ) values (
168	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_table_id, v_invoice_number, now(),
169	    0, 0, 0, 0, 0
170	  )
171	  returning id into v_transaction_id;
172	
173	  for v_item in select * from jsonb_array_elements(p_items)
174	  loop
175	    v_product_id := (v_item ->> 'product_id')::uuid;
176	    v_qty := (v_item ->> 'qty')::numeric;
177	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
178	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
179	
180	    if v_qty is null or v_qty <= 0 then
181	      raise exception 'invalid quantity';
182	    end if;
183	
184	    if v_disc_type not in ('pct', 'amt') then
185	      raise exception 'invalid item discount type';
186	    end if;
187	
188	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
189	      raise exception 'invalid item discount';
190	    end if;
191	
192	    select * into v_product
193	    from public.products p
194	    where p.id = v_product_id
195	      and p.business_id = p_business_id
196	      and p.deleted_at is null;
197	
198	    if not found then
199	      raise exception 'product not found: %', v_product_id;
200	    end if;
201	
202	    v_line_gross := v_product.price * v_qty;
203	    v_item_disc := case v_disc_type
204	      when 'pct' then round(v_line_gross * v_disc / 100)
205	      else least(v_disc * v_qty, v_line_gross)
206	    end;
207	
208	    insert into public.transaction_items (
209	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
210	    ) values (
211	      v_transaction_id, v_product.id, v_product.name, v_product.category,
212	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
213	    );
214	
215	    update public.products
216	    set stock = greatest(0, stock - v_qty)
217	    where id = v_product_id;
218	
219	    -- Consume ingredients per the product's recipe (if any).
220	    for v_recipe in
221	      select pr.ingredient_id, pr.qty as recipe_qty
222	      from public.product_recipes pr
223	      where pr.product_id = v_product_id and pr.ingredient_id is not null
224	    loop
225	      insert into public.transaction_ingredient_consumption (
226	        transaction_id, ingredient_id, qty
227	      ) values (
228	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
229	      );
230	
231	      update public.ingredients
232	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
233	      where id = v_recipe.ingredient_id;
234	    end loop;
235	
236	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
237	    v_total_item_disc := v_total_item_disc + v_item_disc;
238	    v_total_cost := v_total_cost + v_product.cost * v_qty;
239	  end loop;
240	
241	  v_order_disc_amt := case p_order_disc_type
242	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
243	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
244	  end;
245	
246	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
247	
248	  if v_business.service_enabled then
249	    v_service := round(v_subtotal * v_business.service_rate / 100);
250	  end if;
251	
252	  if v_business.tax_enabled then
253	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
254	  end if;
255	
256	  v_total := v_subtotal + v_service + v_tax;
257	
258	  update public.transactions
259	  set subtotal_raw = v_subtotal_raw,
260	      subtotal = v_subtotal,
261	      total_item_disc = v_total_item_disc,
262	      order_disc_amt = v_order_disc_amt,
263	      service = v_service,
264	      tax = v_tax,
265	      total = v_total,
266	      total_cost = v_total_cost,
267	      gross_profit = v_subtotal - v_total_cost
268	  where id = v_transaction_id;
269	
270	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
271	
272	  insert into public.transaction_payments (
273	    transaction_id, method, amount, received, change
274	  ) values (
275	    v_transaction_id, p_payment_method, v_total, p_received, v_change
276	  );
277	
278	  if p_self_order_ids is not null and array_length(p_self_order_ids, 1) > 0 then
279	    update public.self_orders
280	    set status = 'selesai'
281	    where id = any(p_self_order_ids)
282	      and business_id = p_business_id
283	      and status <> 'selesai';
284	  end if;
285	
286	  -- Auto-post the sale to the journal: Kas & Bank debited for the full total,
287	  -- but only (subtotal + service) — the business's actual earnings — is
288	  -- credited to Pendapatan Penjualan. PPN collected from the customer is
289	  -- credited to PPN Keluaran (a liability) instead, since it's held on
290	  -- behalf of the tax office, not revenue. Plus HPP / Persediaan
291	  -- independently whenever this sale had recipe-based cost data, even on a
292	  -- 100%-discount sale where v_total is 0 but stock was still consumed.
293	  v_journal_lines := '[]'::jsonb;
294	  if v_total > 0 then
295	    v_journal_lines := v_journal_lines || jsonb_build_array(
296	      jsonb_build_object('account_code', '1-001', 'debit', v_total, 'credit', 0),
297	      jsonb_build_object('account_code', '4-001', 'debit', 0, 'credit', v_subtotal + v_service)
298	    );
299	    if v_tax > 0 then
300	      v_journal_lines := v_journal_lines || jsonb_build_array(
301	        jsonb_build_object('account_code', '2-200', 'debit', 0, 'credit', v_tax)
302	      );
303	    end if;
304	  end if;
305	  if v_total_cost > 0 then
306	    v_journal_lines := v_journal_lines || jsonb_build_array(
307	      jsonb_build_object('account_code', '5-001', 'debit', v_total_cost, 'credit', 0),
308	      jsonb_build_object('account_code', '1-200', 'debit', 0, 'credit', v_total_cost)
309	    );
310	  end if;
311	  if jsonb_array_length(v_journal_lines) >= 2 then
312	    perform private.post_journal(
313	      p_business_id, now(), 'Penjualan ' || v_invoice_number, 'penjualan', v_transaction_id, v_journal_lines
314	    );
315	  end if;
316	
317	  return query select v_transaction_id, v_invoice_number;
318	end;
319	$$;
320	
321	grant execute on function public.checkout_transaction(
322	  uuid, uuid, jsonb, text, numeric, numeric, text, uuid, uuid[]
323	) to authenticated;
324	
325	-- Void: reverse the original sale's journal entry (swap debit/credit),
326	-- splitting the reversal the same way the original posting was split.
327	create or replace function public.void_transaction(
328	  p_business_id uuid,
329	  p_transaction_id uuid,
330	  p_manager_pin text,
331	  p_reason text default null
332	)
333	returns table (voided_by_name text)
334	language plpgsql
335	security definer
336	set search_path = ''
337	as $$
338	declare
339	  v_manager record;
340	  v_tx record;
341	  v_journal_lines jsonb;
342	begin
343	  if not private.owns_business(p_business_id) then
344	    raise exception 'not authorized';
345	  end if;
346	
347	  -- Hanya PIN milik manajer aktif dari bisnis ini yang diterima. Pesan error
348	  -- sengaja tidak membedakan "PIN salah" vs "bukan manajer".
349	  select c.id, c.name
350	  into v_manager
351	  from public.cashiers c
352	  where c.business_id = p_business_id
353	    and c.role = 'manajer'
354	    and c.active
355	    and c.pin_hash = extensions.crypt(p_manager_pin, c.pin_hash)
356	  limit 1;
357	
358	  if not found then
359	    raise exception 'PIN salah atau tidak memiliki otorisasi';
360	  end if;
361	
362	  select t.id, t.voided, t.total, t.subtotal, t.service, t.tax, t.total_cost, t.invoice_number
363	  into v_tx
364	  from public.transactions t
365	  where t.id = p_transaction_id
366	    and t.business_id = p_business_id
367	  for update;
368	
369	  if not found then
370	    raise exception 'transaction not found';
371	  end if;
372	
373	  if v_tx.voided then
374	    raise exception 'transaksi sudah dibatalkan';
375	  end if;
376	
377	  -- Kembalikan stok produk yang terjual (produk yang sudah dihapus dilewati,
378	  -- sama seperti aplikasi lama).
379	  update public.products p
380	  set stock = p.stock + ti.qty
381	  from public.transaction_items ti
382	  where ti.transaction_id = p_transaction_id
383	    and ti.product_id = p.id
384	    and p.deleted_at is null;
385	
386	  -- Kembalikan stok bahan baku yang terkonsumsi resep saat checkout.
387	  update public.ingredients i
388	  set stock = i.stock + tic.qty
389	  from public.transaction_ingredient_consumption tic
390	  where tic.transaction_id = p_transaction_id
391	    and tic.ingredient_id = i.id;
392	
393	  update public.transactions
394	  set voided = true,
395	      voided_at = now(),
396	      void_reason = nullif(left(trim(p_reason), 200), ''),
397	      voided_by = v_manager.id
398	  where id = p_transaction_id;
399	
400	  v_journal_lines := '[]'::jsonb;
401	  if v_tx.total > 0 then
402	    v_journal_lines := v_journal_lines || jsonb_build_array(
403	      jsonb_build_object('account_code', '4-001', 'debit', v_tx.subtotal + v_tx.service, 'credit', 0),
404	      jsonb_build_object('account_code', '1-001', 'debit', 0, 'credit', v_tx.total)
405	    );
406	    if v_tx.tax > 0 then
407	      v_journal_lines := v_journal_lines || jsonb_build_array(
408	        jsonb_build_object('account_code', '2-200', 'debit', v_tx.tax, 'credit', 0)
409	      );
410	    end if;
411	  end if;
412	  if v_tx.total_cost > 0 then
413	    v_journal_lines := v_journal_lines || jsonb_build_array(
414	      jsonb_build_object('account_code', '1-200', 'debit', v_tx.total_cost, 'credit', 0),
415	      jsonb_build_object('account_code', '5-001', 'debit', 0, 'credit', v_tx.total_cost)
416	    );
417	  end if;
418	  if jsonb_array_length(v_journal_lines) >= 2 then
419	    perform private.post_journal(
420	      p_business_id, now(), 'Void ' || v_tx.invoice_number, 'void', p_transaction_id, v_journal_lines
421	    );
422	  end if;
423	
424	  return query select v_manager.name;
425	end;
426	$$;
427	
428	grant execute on function public.void_transaction(uuid, uuid, text, text) to authenticated;
429

1	-- Formal tutup buku (period closing). Before this, Neraca's "Laba Berjalan"
2	-- was always recomputed from every pendapatan/beban journal line since the
3	-- business's inception — there was no way to lock in a period's profit.
4	-- close_accounting_period() posts a closing entry that zeroes every
5	-- pendapatan/beban account's balance as of the chosen date and rolls the net
6	-- difference into 3-100 Laba Ditahan (retained earnings), which already
7	-- existed in the COA but nothing ever posted to it. Because the zeroing is
8	-- against each account's all-time cumulative balance (not a separate
9	-- "since last close" window), running the same balance query again after a
10	-- closing naturally reflects only activity since that closing — no other
11	-- report needs to change.
12	alter table public.journal_entries drop constraint if exists journal_entries_source_check;
13	alter table public.journal_entries add constraint journal_entries_source_check
14	  check (source in ('manual', 'penjualan', 'void', 'pembelian', 'beban', 'payroll', 'tutup_buku'));
15	
16	create table public.period_closings (
17	  id uuid primary key default gen_random_uuid(),
18	  business_id uuid not null references public.businesses (id) on delete cascade,
19	  period_end date not null,
20	  net_income numeric(14, 2) not null,
21	  journal_entry_id uuid references public.journal_entries (id) on delete set null,
22	  closed_at timestamptz not null default now(),
23	  unique (business_id, period_end)
24	);
25	
26	create index period_closings_business_id_idx on public.period_closings (business_id, period_end desc);
27	
28	alter table public.period_closings enable row level security;
29	
30	-- Read-only from the client — writes only happen through
31	-- close_accounting_period(), which validates ownership itself.
32	create policy "Owner views period closings of own businesses"
33	on public.period_closings for select
34	using (private.owns_business(business_id));
35	
36	create or replace function public.close_accounting_period(
37	  p_business_id uuid,
38	  p_period_end date
39	)
40	returns uuid
41	language plpgsql
42	security definer
43	set search_path = ''
44	as $$
45	declare
46	  v_as_of timestamptz;
47	  v_last_closed date;
48	  v_account record;
49	  v_lines jsonb := '[]'::jsonb;
50	  v_total_pendapatan numeric(14, 2) := 0;
51	  v_total_beban numeric(14, 2) := 0;
52	  v_net_income numeric(14, 2);
53	  v_entry_id uuid;
54	  v_closing_id uuid;
55	begin
56	  if not private.owns_business(p_business_id) then
57	    raise exception 'not authorized';
58	  end if;
59	
60	  if p_period_end > current_date then
61	    raise exception 'tanggal tutup buku tidak boleh di masa depan';
62	  end if;
63	
64	  select max(period_end) into v_last_closed
65	  from public.period_closings
66	  where business_id = p_business_id;
67	
68	  if v_last_closed is not null and p_period_end <= v_last_closed then
69	    raise exception 'tanggal harus setelah tutup buku terakhir (%)', v_last_closed;
70	  end if;
71	
72	  v_as_of := (p_period_end::text || 'T23:59:59+07:00')::timestamptz;
73	
74	  for v_account in
75	    select a.id, a.code, a.type,
76	      coalesce(sum(jl.debit) - sum(jl.credit), 0) as raw_balance
77	    from public.accounts a
78	    left join public.journal_lines jl on jl.account_id = a.id
79	    left join public.journal_entries je on je.id = jl.entry_id and je.date <= v_as_of
80	    where a.business_id = p_business_id and a.type in ('pendapatan', 'beban')
81	    group by a.id, a.code, a.type
82	    having coalesce(sum(jl.debit) - sum(jl.credit), 0) <> 0
83	  loop
84	    if v_account.type = 'pendapatan' then
85	      -- Credit-normal: raw_balance is negative when there's revenue booked.
86	      -- Debit it by the same magnitude to bring the cumulative balance to 0.
87	      v_lines := v_lines || jsonb_build_object(
88	        'account_code', v_account.code, 'debit', -v_account.raw_balance, 'credit', 0
89	      );
90	      v_total_pendapatan := v_total_pendapatan + (-v_account.raw_balance);
91	    else
92	      -- beban is debit-normal: raw_balance is positive when there's expense.
93	      -- Credit it by the same magnitude to zero it out.
94	      v_lines := v_lines || jsonb_build_object(
95	        'account_code', v_account.code, 'debit', 0, 'credit', v_account.raw_balance
96	      );
97	      v_total_beban := v_total_beban + v_account.raw_balance;
98	    end if;
99	  end loop;
100	
101	  if jsonb_array_length(v_lines) = 0 then
102	    raise exception 'tidak ada transaksi pendapatan/beban untuk ditutup pada periode ini';
103	  end if;
104	
105	  v_net_income := v_total_pendapatan - v_total_beban;
106	
107	  if v_net_income >= 0 then
108	    v_lines := v_lines || jsonb_build_object('account_code', '3-100', 'debit', 0, 'credit', v_net_income);
109	  else
110	    v_lines := v_lines || jsonb_build_object('account_code', '3-100', 'debit', -v_net_income, 'credit', 0);
111	  end if;
112	
113	  v_entry_id := private.post_journal(
114	    p_business_id, v_as_of, 'Tutup Buku periode s/d ' || p_period_end::text, 'tutup_buku', null, v_lines
115	  );
116	
117	  insert into public.period_closings (business_id, period_end, net_income, journal_entry_id)
118	  values (p_business_id, p_period_end, v_net_income, v_entry_id)
119	  returning id into v_closing_id;
120	
121	  return v_closing_id;
122	end;
123	$$;
124	
125	grant execute on function public.close_accounting_period(uuid, date) to authenticated;
126

