## 2. `private.post_journal()` and `public.post_journal_entry()`

Both defined in `supabase/migrations/20260708300000_accounting_core.sql`, lines 142–235 (confirmed unchanged in all later migrations via grep — no other file redefines `post_journal` or `post_journal_entry`):

```sql
-- Mechanical double-entry helper — inserts a balanced entry + its lines.
-- Callers (security-definer RPCs) are responsible for auth/ownership checks;
-- this function trusts p_business_id and only enforces that debits = credits.
create or replace function private.post_journal(
  p_business_id uuid,
  p_date timestamptz,
  p_description text,
  p_source text,
  p_source_id uuid,
  p_lines jsonb -- array of {account_code, debit, credit}
)
returns uuid
language plpgsql
set search_path = ''
as $$
declare
  v_entry_id uuid;
  v_line jsonb;
  v_account_id uuid;
  v_total_debit numeric(14, 2) := 0;
  v_total_credit numeric(14, 2) := 0;
  v_debit numeric(14, 2);
  v_credit numeric(14, 2);
begin
  if p_lines is null or jsonb_array_length(p_lines) < 2 then
    raise exception 'journal entry needs at least 2 lines';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_debit := coalesce((v_line ->> 'debit')::numeric, 0);
    v_credit := coalesce((v_line ->> 'credit')::numeric, 0);
    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  end loop;

  if round(v_total_debit, 2) <> round(v_total_credit, 2) then
    raise exception 'unbalanced journal entry: debit % <> credit %', v_total_debit, v_total_credit;
  end if;

  insert into public.journal_entries (business_id, date, description, source, source_id)
  values (p_business_id, p_date, p_description, p_source, p_source_id)
  returning id into v_entry_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    select id into v_account_id
    from public.accounts
    where business_id = p_business_id and code = (v_line ->> 'account_code');

    if v_account_id is null then
      raise exception 'account not found: %', (v_line ->> 'account_code');
    end if;

    insert into public.journal_lines (entry_id, account_id, debit, credit)
    values (
      v_entry_id,
      v_account_id,
      coalesce((v_line ->> 'debit')::numeric, 0),
      coalesce((v_line ->> 'credit')::numeric, 0)
    );
  end loop;

  return v_entry_id;
end;
$$;

-- Public RPC for manual journal entries from the client.
create or replace function public.post_journal_entry(
  p_business_id uuid,
  p_date timestamptz,
  p_description text,
  p_lines jsonb -- array of {account_code, debit, credit}
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entry_id uuid;
begin
  if not private.owns_business(p_business_id) then
    raise exception 'not authorized';
  end if;

  if p_description is null or length(trim(p_description)) = 0 then
    raise exception 'description required';
  end if;

  v_entry_id := private.post_journal(
    p_business_id, coalesce(p_date, now()), p_description, 'manual', null, p_lines
  );

  return v_entry_id;
end;
$$;
```

**Signature/shape**: `p_lines` is a `jsonb` array of `{account_code: text, debit: numeric, credit: numeric}` objects (looked up by `code`, not `id` — so a new account code must exist in `public.accounts` for that business before you can post to it). Requires ≥2 lines and debits=credits exactly (rounded to 2 decimals), or it raises. `p_source` is constrained by the `journal_entries_source_check` check constraint, currently: `'manual', 'penjualan', 'void', 'pembelian', 'beban', 'payroll', 'tutup_buku'` (from `20260710130000_period_closing.sql`, line 12-14 — it dropped and recreated this check constraint). **If you want a distinct source tag for ticket sales** (e.g. `'tiket'` instead of reusing `'penjualan'`), you'll need to `alter table ... drop constraint ... add constraint` again to extend the allowed values — reusing `'penjualan'`/`'void'` also works and requires no schema change, at the cost of not being able to filter tiket-journal-entries by source alone (you'd filter by `source_id` join to `ticket_transactions` instead, or by description prefix).

`private.post_journal` is **not** `security definer` — it relies on the caller (a `security definer` RPC) having already done ownership checks; it "trusts p_business_id."

